SELECT
SUM(CASE WHEN is_company_ticket = 1 THEN 1 ELSE 0 END) AS workPermitCount,
SUM(CASE WHEN is_company_alarm = 1 THEN 1 ELSE 0 END) AS personnelLocationCount,
SUM(CASE WHEN isbuild = 1 THEN 1 ELSE 0 END) AS dualControlCount
FROM accept_company
WHERE 1=1

    AND countycode = #{countycode}


    AND yq_type = #{yqType}


    AND is_scqy = #{isScqy}

SELECT
CASE WHEN isbuild = 1 THEN '已接入' ELSE '未接入' END AS name,
COUNT(*) AS value
FROM accept_company
WHERE deleted = 0

    AND countycode = #{countycode}


    AND yq_type = #{yqType}


    AND code IN

        #{code}



    AND is_scqy = #{isScqy}

GROUP BY isbuild

SELECT
SUM(CASE WHEN run_level = '优' THEN 1 ELSE 0 END) AS excellent,
SUM(CASE WHEN run_level = '良' THEN 1 ELSE 0 END) AS good,
SUM(CASE WHEN run_level = '中' THEN 1 ELSE 0 END) AS medium,
SUM(CASE WHEN run_level = '差' THEN 1 ELSE 0 END) AS poor
FROM accept_company
WHERE deleted = 0

    AND countycode = #{countycode}


    AND yq_type = #{yqType}


    AND code IN

        #{code}



    AND is_scqy = #{isScqy}

